FILES = json.loads("{\"proj_sec/extractor.py\":{\"updated\":\"from __future__ import annotations\\n\\nimport hashlib\\nimport json\\nimport re\\nfrom pathlib import Path\\nfrom typing import Callable\\n\\nimport yaml\\n\\nfrom .common import MODEL_ID, PROMPT_TYPES, normalize, write_json, write_text\\nfrom .pdfio import Document, Section, read_pdf, split_sections\\nfrom .prompts import BUILDERS\\nfrom .selection import candidate_excerpts, candidates, parse_ids, source_kind\\n\\n\\ndef validate_documents(first: Path | str, second: Path | str) -> tuple[Document, Document]:\\n    \\\"\\\"\\\"Task 1, function 1: validate and read both inputs, including identical PDFs.\\\"\\\"\\\"\\n    left = read_pdf(first)\\n    right = left if Path(first).resolve() == Path(second).resolve() else read_pdf(second)\\n    return left, right\\n\\n\\ndef write_llm_log(records: list[dict], path: Path | str) -> Path:\\n    \\\"\\\"\\\"Task 1, function 6: save all actual requests and raw model responses.\\\"\\\"\\\"\\n    blocks = []\\n    for record in records:\\n        blocks.append(\\n            f\\\"*LLM Name*\\\\n{record['model']}\\\\n\\\"\\n            f\\\"*Prompt Used*\\\\n{record['prompt']}\\\\n\\\"\\n            f\\\"*Prompt Type*\\\\n{record['prompt_type']}\\\\n\\\"\\n            f\\\"*LLM Output*\\\\n{record['output']}\\\\n\\\"\\n            f\\\"*Source*\\\\n{record.get('source', '')}\\\\n\\\"\\n            f\\\"*Status*\\\\n{record.get('status', 'unvalidated')}\\\\n\\\"\\n            f\\\"*Cached*\\\\n{record.get('cached', False)}\\\\n\\\"\\n            f\\\"*Syntax Repair*\\\\n{record.get('syntax_repair') or 'none'}\\\\n\\\"\\n            f\\\"*Element Name Source*\\\\n{record.get('element_name_source', 'not recorded')}\\\\n\\\"\\n            f\\\"*Source Element Name*\\\\n{record.get('source_element_name', 'not recorded')}\\\\n\\\"\\n            f\\\"*Model Element Name*\\\\n{json.dumps(record.get('model_element_name'), ensure_ascii=False)}\\\\n\\\"\\n            f\\\"*Model Name Differs*\\\\n{record.get('model_name_differs', False)}\\\\n\\\"\\n            f\\\"*Output Format*\\\\n{record.get('output_format', 'not recorded')}\\\\n\\\"\\n            f\\\"*Model Selected IDs*\\\\n{json.dumps(record.get('selected_ids'))}\\\\n\\\"\\n            f\\\"*Model Selected Requirements*\\\\n{json.dumps(record.get('model_selected_requirements'), ensure_ascii=False)}\\\\n\\\"\\n            f\\\"*Included Source IDs*\\\\n{json.dumps(record.get('included_source_ids'))}\\\\n\\\"\\n            f\\\"*Included Source Requirements*\\\\n{json.dumps(record.get('included_source_requirements'), ensure_ascii=False)}\\\\n\\\"\\n            f\\\"*Context Added IDs*\\\\n{json.dumps(record.get('context_added_ids'))}\\\\n\\\"\\n            f\\\"*Coverage Policy*\\\\n{record.get('coverage_policy', 'not recorded')}\\\\n\\\"\\n            f\\\"*Unselected Source IDs*\\\\n{json.dumps(record.get('unselected_source_ids'))}\\\\n\\\"\\n            f\\\"*Review Flags*\\\\n{json.dumps(record.get('review_flags', []))}\\\\n\\\"\\n            f\\\"*Decoding Constraint*\\\\n{record.get('decoding_constraint', 'unconstrained')}\\\\n\\\"\\n        )\\n    return write_text(path, \\\"\\\\n\\\".join(blocks))\\n\\n\\ndef _decode_response(raw: str) -> tuple[object, str | None]:\\n    text = raw.strip()\\n    if text.startswith(\\\"```\\\"):\\n        fenced = re.fullmatch(r\\\"```(?:json)?[ \\\\t]*\\\\r?\\\\n(.*?)\\\\r?\\\\n?```\\\", text,\\n                              flags=re.DOTALL | re.IGNORECASE)\\n        if fenced is None:\\n            raise ValueError(\\\"Gemma response is not a complete JSON object\\\")\\n        text = fenced.group(1).strip()\\n    try:\\n        return json.loads(text), None\\n    except (ValueError, TypeError) as original:\\n        # Accept one requirements object followed solely by redundant closing\\n        # delimiters. Never discard trailing text, another value, or an opener.\\n        if text.startswith(\\\"{\\\"):\\n            try:\\n                value, end = json.JSONDecoder().raw_decode(text)\\n            except (ValueError, TypeError):\\n                pass\\n            else:\\n                trailing = text[end:].strip()\\n                if (isinstance(value, dict) and set(value) in ({\\\"requirements\\\"}, {\\\"name\\\", \\\"requirements\\\"})\\n                        and re.fullmatch(r\\\"[\\\\]}\\\\s]{1,32}\\\", trailing)):\\n                    return value, \\\"removed redundant closing delimiters after complete JSON object\\\"\\n        # The observed response closed its complete requirements array but\\n        # omitted exactly the outer object's final brace. Never add a value,\\n        # quotation mark, array bracket, or more than one closing brace.\\n        if text.startswith(\\\"{\\\") and text.endswith(\\\"]\\\"):\\n            try:\\n                value = json.loads(text + \\\"}\\\")\\n            except (ValueError, TypeError):\\n                pass\\n            else:\\n                if isinstance(value, dict) and set(value) in ({\\\"requirements\\\"}, {\\\"name\\\", \\\"requirements\\\"}):\\n                    return value, \\\"appended one missing final object brace\\\"\\n        raise ValueError(\\\"Gemma response is not a complete JSON object\\\") from original\\n\\n\\ndef _parse_legacy_response(raw: str, section) -> dict:\\n    value, _ = _decode_response(raw)\\n    if not isinstance(value, dict):\\n        raise ValueError(\\\"Gemma response must be a JSON object with requirements\\\")\\n    # The PDF heading identifies this source block before the LLM is called.\\n    # Names are source metadata; only requirement selection depends on Gemma.\\n    # Keep the model's own label in the audit instead of using it as the KDE key.\\n    requirements = value.get(\\\"requirements\\\")\\n    if not isinstance(requirements, list) or not requirements:\\n        raise ValueError(\\\"Gemma must return at least one requirement\\\")\\n    source = normalize(section.text)\\n    cleaned = []\\n    for requirement in requirements:\\n        if not isinstance(requirement, str) or not normalize(requirement):\\n            raise ValueError(\\\"Requirements must be nonempty strings\\\")\\n        requirement = normalize(requirement)\\n        if requirement not in source:\\n            raise ValueError(\\\"Gemma returned a requirement without a matching source excerpt\\\")\\n        if requirement not in cleaned:\\n            cleaned.append(requirement)\\n    remediation = re.search(r\\\"(?:^|\\\\n)Remediation:[ \\\\t]*\\\\n(.*)\\\\Z\\\", section.text, re.DOTALL)\\n    if remediation and (remediation_text := normalize(remediation.group(1))):\\n        if not any(r in remediation_text or remediation_text in r for r in cleaned):\\n            raise ValueError(\\\"Gemma omitted the Remediation actions; include exact excerpts from Remediation\\\")\\n    return {\\\"name\\\": section.title, \\\"requirements\\\": sorted(cleaned), \\\"source_ids\\\": [section.cis_id]}\\n\\n\\n\\n\\ndef _analyze_response(raw: str, section: Section, *,\\n                      retain_description_context: bool = False) -> tuple[dict, dict]:\\n    # The legacy keyword is accepted for compatibility but cannot add requirements.\\n    stripped = raw.strip()\\n    if stripped.startswith(\\\"```\\\") and \\\"\\\\n\\\" in stripped:\\n        stripped = stripped.split(\\\"\\\\n\\\", 1)[1].lstrip()\\n    # Legacy objects remain readable for cache reuse; new requests use IDs.\\n    legacy = stripped.startswith(\\\"{\\\") and not re.match(r'\\\\{\\\\s*\\\"ids\\\"\\\\s*:', stripped)\\n    if legacy:\\n        value = _parse_legacy_response(raw, section)\\n        decoded, repair = _decode_response(raw)\\n        selected = value[\\\"requirements\\\"]\\n        model_name = decoded.get(\\\"name\\\")\\n        metadata = {\\\"output_format\\\": \\\"legacy-json\\\", \\\"syntax_repair\\\": repair,\\n                    \\\"model_element_name\\\": model_name, \\\"model_name_differs\\\": model_name != section.title,\\n                    \\\"selected_ids\\\": None, \\\"model_selected_requirements\\\": selected}\\n    else:\\n        spans = candidate_excerpts(section)\\n        ids = parse_ids(raw, len(spans), allow_empty=source_kind(section) == \\\"Description\\\")\\n        selected = [spans[i - 1] for i in ids]\\n        value = {\\\"name\\\": section.title, \\\"requirements\\\": selected, \\\"source_ids\\\": [section.cis_id]}\\n        metadata = {\\\"output_format\\\": \\\"source-excerpt-ids\\\", \\\"syntax_repair\\\": None,\\n                    \\\"model_element_name\\\": None, \\\"model_name_differs\\\": False,\\n                    \\\"selected_ids\\\": ids, \\\"model_selected_requirements\\\": selected}\\n    # Only the actual Gemma selection belongs in requirements. The complete\\n    # source remains available separately for review; it must never backfill a\\n    # NONE response or a partial model selection.\\n    spans = candidate_excerpts(section)\\n    unselected = [i for i, span in enumerate(spans, 1)\\n                  if not any(normalize(span) in normalize(requirement)\\n                             for requirement in selected)]\\n    value[\\\"requirements\\\"] = sorted(set(selected))\\n    metadata.update({\\\"element_name_source\\\": \\\"PDF heading\\\",\\n                     \\\"source_element_name\\\": section.title,\\n                     \\\"coverage_policy\\\": \\\"model-selected-only\\\",\\n                     \\\"included_source_ids\\\": metadata[\\\"selected_ids\\\"],\\n                     \\\"included_source_requirements\\\": value[\\\"requirements\\\"],\\n                     \\\"context_added_ids\\\": [],\\n                     \\\"source_context_requirements\\\": spans,\\n                     \\\"unselected_source_ids\\\": unselected,\\n                     \\\"review_flags\\\": ([\\\"unselected-source-excerpts\\\"] if unselected else [])\\n                                     + ([\\\"no-model-selection\\\"] if not selected else [])})\\n\\n    return value, metadata\\n\\n\\ndef _parse_response(raw: str, section) -> dict:\\n    return _analyze_response(raw, section)[0]\\n\\n\\ndef _source_blocks(section: Section) -> list[tuple[str, Section]]:\\n    matches = list(re.finditer(\\n        r\\\"^(Description|Remediation):[ \\\\t]*\\\\n(.*?)(?=^(?:Description|Remediation):|\\\\Z)\\\",\\n        section.text, re.MULTILINE | re.DOTALL))\\n    if not matches:\\n        return [(\\\"Source\\\", section)]\\n    blocks = [(m.group(1), Section(section.cis_id, section.title,\\n                                   m.group(1) + \\\":\\\\n\\\" + m.group(2).strip()))\\n              for m in matches if normalize(m.group(2))]\\n    if not blocks:\\n        raise ValueError(f\\\"No nonempty source blocks for {section.cis_id}\\\")\\n    return blocks\\n\\n\\ndef extract_kdes(documents: tuple[Document, Document], output_dir: Path | str,\\n                 generate: Callable[[str], str], *, prompt_types=PROMPT_TYPES,\\n                 model_identity: str = MODEL_ID, retries: int = 2,\\n                 cache_dir: Path | str | None = None,\\n                 section_limit: int | None = None, progress: Callable[[dict], None] | None = None) -> dict[str, tuple[Path, Path]]:\\n    \\\"\\\"\\\"Task 1, function 5: run each prompt strategy and save document-named YAMLs.\\n\\n    A supplied generator permits isolated unit tests. The production CLI always\\n    uses the required Gemma worker; it does not provide a mock-inference mode.\\n    \\\"\\\"\\\"\\n    output_dir = Path(output_dir)\\n    if not prompt_types or any(style not in BUILDERS for style in prompt_types):\\n        raise ValueError(\\\"Unknown or empty prompt type selection\\\")\\n    if section_limit is not None and (isinstance(section_limit, bool)\\n                                      or not isinstance(section_limit, int) or section_limit < 1):\\n        raise ValueError(\\\"section_limit must be a positive integer or None\\\")\\n    if isinstance(retries, bool) or not isinstance(retries, int) or retries < 0:\\n        raise ValueError(\\\"retries must be a nonnegative integer\\\")\\n    sections_by_hash = {doc.sha256: split_sections(doc)[:section_limit] for doc in documents}\\n    records, outputs, prompt_blocks = [], {}, {style: [] for style in prompt_types}\\n    source_context = []\\n    extraction_complete = False\\n    cache_dir = Path(cache_dir) if cache_dir is not None else output_dir / \\\"cache\\\"\\n    cache_dir.mkdir(parents=True, exist_ok=True)\\n\\n    def flush_audit():\\n        review_items = [\\n            {key: entry[key] for key in (\\\"file\\\", \\\"side\\\", \\\"cis_id\\\", \\\"prompt_type\\\",\\n                                         \\\"source_field\\\", \\\"unselected_source_ids\\\", \\\"review_flags\\\")}\\n            for entry in source_context if entry[\\\"review_flags\\\"]\\n        ]\\n        write_json(output_dir / \\\"source-context.json\\\", {\\n            \\\"requirements_policy\\\": \\\"model-selected-only\\\",\\n            \\\"purpose\\\": \\\"Supplemental source for review; not comparator requirements\\\",\\n            \\\"blocks\\\": source_context,\\n        })\\n        write_json(output_dir / \\\"extraction-review.json\\\", {\\n            \\\"status\\\": (\\\"completed-with-review-items\\\" if review_items else \\\"completed\\\")\\n                      if extraction_complete else \\\"incomplete\\\",\\n            \\\"requirements_policy\\\": \\\"model-selected-only\\\",\\n            \\\"processed_source_blocks\\\": len(source_context),\\n            \\\"blocks_with_review_items\\\": len(review_items),\\n            \\\"items\\\": review_items,\\n            \\\"limitations\\\": \\\"Unselected excerpts may be background or missed requirements. \\\"\\n                           \\\"Format/source validation does not establish semantic accuracy.\\\",\\n        })\\n        write_llm_log(records, output_dir / \\\"llm-output.txt\\\")\\n        write_text(output_dir / \\\"PROMPT.md\\\", \\\"# Actual extraction prompts\\\\n\\\\n\\\" + \\\"\\\\n\\\".join(\\n            f\\\"## {style}\\\\n\\\\n\\\" + \\\"\\\\n\\\".join(prompt_blocks[style]) for style in prompt_types))\\n\\n    for style in prompt_types:\\n        paths = []\\n        for side, document in zip((\\\"left\\\", \\\"right\\\"), documents):\\n            elements = {}\\n            for index, section in enumerate(sections_by_hash[document.sha256], 1):\\n                merged_requirements = set()\\n                blocks = _source_blocks(section)\\n                for field, part in blocks:\\n                    prompt = BUILDERS[style](part, output_format=\\\"ids\\\")\\n                    key = hashlib.sha256((\\\"source-selection-trie-v1\\\\n\\\" + model_identity + \\\"\\\\n\\\" + field + \\\"\\\\n\\\" + prompt).encode()).hexdigest()\\n                    cache_file = cache_dir / f\\\"{key}.json\\\"\\n                    previous_key = hashlib.sha256((\\\"source-selection-v1\\\\n\\\" + model_identity + \\\"\\\\n\\\" + field + \\\"\\\\n\\\" + prompt).encode()).hexdigest()\\n                    previous_file = cache_dir / f\\\"{previous_key}.json\\\"\\n                    legacy_prompt = BUILDERS[style](part)\\n                    legacy_key = hashlib.sha256((\\\"source-block-v1\\\\n\\\" + model_identity + \\\"\\\\n\\\" + field + \\\"\\\\n\\\" + legacy_prompt).encode()).hexdigest()\\n                    legacy_file = cache_dir / f\\\"{legacy_key}.json\\\"\\n                    existing = next((path for path in (cache_file, previous_file, legacy_file) if path.exists()), None)\\n                    event = {\\\"file\\\": document.path.name, \\\"side\\\": side, \\\"cis_id\\\": section.cis_id,\\n                             \\\"prompt_type\\\": style, \\\"source_field\\\": field, \\\"section\\\": index,\\n                             \\\"sections\\\": len(sections_by_hash[document.sha256])}\\n                    if progress:\\n                        progress({**event, \\\"status\\\": \\\"starting\\\"})\\n                    if existing is not None:\\n                        cached = json.loads(existing.read_text(encoding=\\\"utf-8\\\"))\\n                        value, metadata = _analyze_response(\\n                            cached[\\\"raw\\\"], part)\\n                        metadata[\\\"decoding_constraint\\\"] = cached.get(\\\"decoding_constraint\\\", \\\"unconstrained\\\")\\n                        used_prompt = cached.get(\\\"prompt_used\\\", legacy_prompt if existing == legacy_file else prompt)\\n                        prompt_blocks[style].append(f\\\"### Cached request: {side}, {section.cis_id}/{field}\\\\n\\\\n```text\\\\n{used_prompt}\\\\n```\\\\n\\\")\\n                        records.append({\\\"model\\\": MODEL_ID, \\\"prompt\\\": used_prompt, \\\"prompt_type\\\": style,\\n                                        \\\"output\\\": cached[\\\"raw\\\"], \\\"source\\\": f\\\"{side}/{document.path.name}:{section.cis_id}/{field}\\\",\\n                                        \\\"status\\\": \\\"validated\\\", \\\"cached\\\": True, **metadata})\\n                    else:\\n                        used_prompt = prompt\\n                        prompt_blocks[style].append(f\\\"### {side}: {document.path.name}, {section.cis_id}/{field}\\\\n\\\\n```text\\\\n{prompt}\\\\n```\\\\n\\\")\\n                        for attempt in range(retries + 1):\\n                            select = getattr(generate, \\\"select_ids\\\", None)\\n                            if callable(select):\\n                                raw = select(used_prompt, len(candidate_excerpts(part)),\\n                                             allow_empty=source_kind(part) == \\\"Description\\\")\\n                                decoding_constraint = \\\"source-id-trie-v1\\\"\\n                            else:\\n                                raw = generate(used_prompt)\\n                                decoding_constraint = \\\"unconstrained-test-generator\\\"\\n                            record = {\\\"model\\\": MODEL_ID, \\\"prompt\\\": used_prompt, \\\"prompt_type\\\": style,\\n                                      \\\"output\\\": raw, \\\"source\\\": f\\\"{side}/{document.path.name}:{section.cis_id}/{field}\\\",\\n                                      \\\"status\\\": \\\"unvalidated\\\", \\\"cached\\\": False}\\n                            records.append(record)\\n                            try:\\n                                # Preserve any bounded legacy syntax note even if\\n                                # later source/content validation rejects the response.\\n                                try:\\n                                    record[\\\"syntax_repair\\\"] = _decode_response(raw)[1]\\n                                except ValueError:\\n                                    pass\\n                                value, metadata = _analyze_response(\\n                                    raw, part)\\n                            except ValueError as exc:\\n                                record[\\\"status\\\"] = str(exc)\\n                                flush_audit()\\n                                if progress:\\n                                    progress({**event, \\\"status\\\": \\\"validation-failed\\\", \\\"attempt\\\": attempt + 1, \\\"error\\\": str(exc)})\\n                                if attempt == retries:\\n                                    raise ValueError(f\\\"{document.path.name}, {section.cis_id}/{field}, {style}: {exc}\\\") from exc\\n                                used_prompt = (prompt + f\\\"\\\\nCorrection required (attempt {attempt + 2}): {exc}.\\\\n\\\"\\n                                               \\\"Return only existing excerpt numbers separated by commas. Do not rewrite source text.\\\\n\\\")\\n                                prompt_blocks[style].append(f\\\"### Correction attempt: {side}, {section.cis_id}/{field}\\\\n\\\\n```text\\\\n{used_prompt}\\\\n```\\\\n\\\")\\n                            else:\\n                                metadata[\\\"decoding_constraint\\\"] = decoding_constraint\\n                                record.update(metadata)\\n                                record[\\\"status\\\"] = \\\"validated\\\"\\n                                write_json(cache_file, {\\\"raw\\\": raw, \\\"prompt_used\\\": used_prompt,\\n                                                      \\\"model_identity\\\": model_identity, \\\"source_field\\\": field, **metadata})\\n                                break\\n                    merged_requirements.update(value[\\\"requirements\\\"])\\n                    source_context.append({\\n                        **event, \\\"input_sha256\\\": document.sha256,\\n                        \\\"source_text\\\": part.text,\\n                        \\\"source_excerpts\\\": metadata[\\\"source_context_requirements\\\"],\\n                        \\\"model_selected_ids\\\": metadata[\\\"selected_ids\\\"],\\n                        \\\"model_selected_requirements\\\": metadata[\\\"model_selected_requirements\\\"],\\n                        \\\"unselected_source_ids\\\": metadata[\\\"unselected_source_ids\\\"],\\n                        \\\"review_flags\\\": metadata[\\\"review_flags\\\"],\\n                    })\\n                    flush_audit()\\n                    if progress:\\n                        progress({**event, \\\"status\\\": \\\"cache-hit\\\" if records[-1][\\\"cached\\\"] else \\\"validated\\\"})\\n                if not merged_requirements:\\n                    raise ValueError(f\\\"{document.path.name}, {section.cis_id}: no requirements selected\\\")\\n                elements[f\\\"element{index}\\\"] = {\\\"name\\\": section.title,\\n                                                \\\"requirements\\\": sorted(merged_requirements),\\n                                                \\\"source_ids\\\": [section.cis_id]}\\n            path = output_dir / style / f\\\"{side}-{document.path.stem}-kdes.yaml\\\"\\n            write_text(path, yaml.safe_dump(elements, allow_unicode=True, sort_keys=False))\\n            paths.append(path)\\n        outputs[style] = tuple(paths)\\n    extraction_complete = True\\n    flush_audit()\\n    return outputs\\n\",\"original_blob\":\"52cc825acfcc6c369b6eb23e3597ae5085da5dc8\"},\"proj_sec/__init__.py\":{\"updated\":\"\\\"\\\"\\\"Compare CIS security requirements and select Dockerfile checks.\\\"\\\"\\\"\\n\\n__version__ = \\\"0.4.0\\\"\\n\",\"original_blob\":\"89ee7a14528be9e72da5344544352cc80070b0db\"},\"tests/test_source_selection.py\":{\"updated\":\"import hashlib\\nimport json\\nfrom pathlib import Path\\nimport tempfile\\nimport unittest\\n\\nfrom proj_sec.common import load_kdes, normalize\\nfrom proj_sec.extractor import _analyze_response, _parse_response, _source_blocks, extract_kdes, validate_documents\\nfrom proj_sec.pdfio import Section, split_sections\\nfrom proj_sec.prompts import BUILDERS\\nfrom proj_sec.selection import candidate_excerpts, parse_ids\\nfrom tests.helpers import TEXT, make_pdf\\n\\n\\nREMEDIATION = '''Edit the Docker daemon configuration file to ensure that icc is disabled. It should include\\nthe following setting\\n\\\"icc\\\": false\\nAlernatively, run the docker daemon directly and pass --icc=false as an argument.\\nFor Example,\\ndockerd --icc=false\\nAlternatively, you can follow the Docker documentation and create a custom network\\nand only join containers that need to communicate to that custom network. The --icc\\nparameter only applies to the default docker bridge, if custom networks are used then\\nthe approach of segmenting networks should be adopted instead.\\nIn order for this control to be fully effective, all containers connected to the docker0\\nbridge should drop the NET_RAW capability, otherwise a compromised container could\\nuse raw ethernet packets to communicate with other containers despite this restriction.'''\\n\\n\\nclass SourceSelectionTests(unittest.TestCase):\\n    def setUp(self):\\n        self.section = Section('2.2', 'Ensure network traffic is restricted between containers on the default bridge',\\n                               'Remediation:\\\\n' + REMEDIATION)\\n\\n    def test_partial_model_selections_do_not_backfill_unselected_remediation(self):\\n        spans = candidate_excerpts(self.section)\\n        self.assertEqual(len(spans), 5)\\n        for raw, selected in [('1, 3\\\\n', [1, 3]), ('1,3,5\\\\n', [1, 3, 5]), ('1, 4\\\\n', [1, 4])]:\\n            with self.subTest(raw=raw):\\n                value, metadata = _analyze_response(raw, self.section)\\n                expected = [spans[i - 1] for i in selected]\\n                self.assertEqual(set(value['requirements']), set(expected))\\n                self.assertEqual(metadata['model_selected_requirements'], expected)\\n                self.assertEqual(metadata['selected_ids'], selected)\\n                self.assertEqual(metadata['included_source_ids'], selected)\\n                self.assertEqual(metadata['context_added_ids'], [])\\n                self.assertEqual(metadata['coverage_policy'], 'model-selected-only')\\n                self.assertEqual(metadata['source_context_requirements'], spans)\\n                self.assertEqual(metadata['unselected_source_ids'],\\n                                 [i for i in range(1, 6) if i not in selected])\\n                self.assertEqual(metadata['review_flags'], ['unselected-source-excerpts'])\\n                self.assertTrue(all(requirement in normalize(REMEDIATION)\\n                                    for requirement in value['requirements']))\\n\\n    def test_candidate_splitting_preserves_every_non_whitespace_character(self):\\n        spans = candidate_excerpts(self.section)\\n        self.assertEqual(''.join(''.join(s.split()) for s in spans), ''.join(REMEDIATION.split()))\\n\\n    def test_description_remains_model_selected_and_can_have_no_obligations(self):\\n        section = Section('x', 'A source heading', 'Description:\\\\nBackground information. Require administrator access.')\\n        value, metadata = _analyze_response('2', section)\\n        self.assertEqual(value['requirements'], ['Require administrator access.'])\\n        self.assertEqual(metadata['context_added_ids'], [])\\n        self.assertEqual(_parse_response('NONE', section)['requirements'], [])\\n        with self.assertRaises(ValueError):\\n            _parse_response('NONE', self.section)\\n\\n    def test_bad_ids_and_arbitrary_prose_cannot_produce_source_requirements(self):\\n        for raw in ('0', '6', '-1', '[true]', '[1.5]', '1 because 3', '1,3 trailing text', '[]'):\\n            with self.subTest(raw=raw):\\n                with self.assertRaises(ValueError):\\n                    _parse_response(raw, self.section)\\n        self.assertEqual(parse_ids('```text\\\\n1,3\\\\n```', 5), [1, 3])\\n        self.assertEqual(parse_ids('{\\\"ids\\\":[1,3]}', 5), [1, 3])\\n\\n    def test_prompt_builders_request_ids_and_keep_json_builders_for_old_cache_keys(self):\\n        for style, builder in BUILDERS.items():\\n            with self.subTest(style=style):\\n                prompt = builder(self.section, output_format='ids')\\n                self.assertIn('Return ONLY the selected excerpt numbers', prompt)\\n                self.assertIn('[5] In order for this control', prompt)\\n                self.assertNotIn('Required response structure', prompt)\\n                self.assertIn('Required response structure', builder(self.section))\\n\\n    def test_legacy_cache_is_reused_without_claiming_a_new_prompt_was_sent(self):\\n        with tempfile.TemporaryDirectory() as tmp:\\n            root = Path(tmp)\\n            pdf = root / 'cis.pdf'\\n            make_pdf(pdf, TEXT)\\n            documents = validate_documents(pdf, pdf)\\n            section = split_sections(documents[0])[0]\\n            cache = root / 'cache'\\n            cache.mkdir()\\n            identity = 'same-model'\\n            for field, part in _source_blocks(section):\\n                prompt = BUILDERS['zero-shot'](part)\\n                key = hashlib.sha256(('source-block-v1\\\\n' + identity + '\\\\n' + field + '\\\\n' + prompt).encode()).hexdigest()\\n                requirement = 'Set USER app.' if field == 'Remediation' else 'Containers should run as a non-root user.'\\n                (cache / f'{key}.json').write_text(json.dumps({'raw': json.dumps({'name': part.title, 'requirements': [requirement]}),\\n                                                            'prompt_used': prompt, 'model_identity': identity}))\\n            def no_generation(prompt):\\n                self.fail('A validated legacy cache response should have been reused.')\\n            result = extract_kdes(documents, root / 'out', no_generation, cache_dir=cache,\\n                                  model_identity=identity, section_limit=1, prompt_types=('zero-shot',))\\n            self.assertEqual(len(load_kdes(result['zero-shot'][0])), 1)\\n            log = (root / 'out/llm-output.txt').read_text()\\n            self.assertIn('*Cached*\\\\nTrue', log)\\n            self.assertIn('*Output Format*\\\\nlegacy-json', log)\\n            actual_prompts = (root / 'out/PROMPT.md').read_text()\\n            self.assertIn('Required response structure', actual_prompts)\\n            self.assertNotIn('Source excerpts:', actual_prompts)\\n\\n    def test_numeric_responses_are_cached_with_actual_selections_and_context_policy(self):\\n        with tempfile.TemporaryDirectory() as tmp:\\n            root = Path(tmp)\\n            pdf = root / 'cis.pdf'\\n            make_pdf(pdf, TEXT)\\n            calls = []\\n            def generate(prompt):\\n                calls.append(prompt)\\n                self.assertIn('selected excerpt numbers', prompt)\\n                return '1\\\\n'\\n            options = {'model_identity': 'same-model', 'cache_dir': root / 'cache',\\n                       'section_limit': 1, 'prompt_types': ('zero-shot',)}\\n            documents = validate_documents(pdf, pdf)\\n            extract_kdes(documents, root / 'one', generate, **options)\\n            extract_kdes(documents, root / 'two', generate, **options)\\n            self.assertEqual(len(calls), 2)\\n            cache = [json.loads(p.read_text()) for p in (root / 'cache').glob('*.json')]\\n            self.assertTrue(all(entry['raw'] == '1\\\\n' for entry in cache))\\n            self.assertTrue(all(entry['selected_ids'] == [1] for entry in cache))\\n            log = (root / 'two/llm-output.txt').read_text()\\n            self.assertIn('*Model Selected IDs*\\\\n[1]', log)\\n            self.assertIn('*Coverage Policy*\\\\nmodel-selected-only', log)\\n\\n\\nif __name__ == '__main__':\\n    unittest.main()\\n\",\"original_blob\":\"4436fca1b6697fe645009bd615c7e8b19d6420c2\"},\"tests/test_description_context.py\":{\"updated\":\"import json\\nimport tempfile\\nimport unittest\\nfrom pathlib import Path\\n\\nfrom proj_sec.common import NO_REQUIREMENTS, load_kdes\\nfrom proj_sec.comparator import compare_requirements, load_yaml_pair\\nfrom proj_sec.extractor import _analyze_response, extract_kdes, validate_documents\\nfrom proj_sec.pdfio import Section\\nfrom tests.helpers import TEXT, is_remediation_prompt, make_pdf\\n\\n\\nclass DescriptionContextTests(unittest.TestCase):\\n    def test_none_preserves_source_context_without_creating_a_requirement(self):\\n        section = Section('5.6', 'Restrict mounts',\\n                          'Description:\\\\nDo not mount sensitive directories.\\\\n/\\\\n/lib\\\\n/lib64')\\n        value, metadata = _analyze_response('NONE', section, retain_description_context=True)\\n        self.assertEqual(value['requirements'], [])\\n        self.assertIn('/lib64', ' '.join(metadata['source_context_requirements']))\\n        self.assertEqual(metadata['selected_ids'], [])\\n        self.assertEqual(metadata['model_selected_requirements'], [])\\n        self.assertEqual(metadata['context_added_ids'], [])\\n        self.assertEqual(metadata['coverage_policy'], 'model-selected-only')\\n        self.assertIn('no-model-selection', metadata['review_flags'])\\n\\n    def test_partial_legacy_copy_does_not_backfill_an_omitted_qualifier(self):\\n        section = Section('x', 'Audit configuration',\\n                          'Description:\\\\nAudit /etc/service.conf if applicable.')\\n        raw = '{\\\"name\\\":\\\"Audit configuration\\\",\\\"requirements\\\":[\\\"Audit /etc/service.conf\\\"]}'\\n        value, metadata = _analyze_response(raw, section, retain_description_context=True)\\n        self.assertEqual(value['requirements'], ['Audit /etc/service.conf'])\\n        self.assertEqual(metadata['source_context_requirements'],\\n                         ['Audit /etc/service.conf if applicable.'])\\n        self.assertEqual(metadata['unselected_source_ids'], [1])\\n\\n    def test_missed_lib64_change_is_flagged_separately_and_not_injected_on_resume(self):\\n        with tempfile.TemporaryDirectory() as tmp:\\n            root = Path(tmp)\\n            old, new = root/'old.pdf', root/'new.pdf'\\n            old_text = TEXT.replace('Containers should run as a non-root user.',\\n                                    'Do not mount sensitive directories / /lib /usr.')\\n            new_text = old_text.replace('/ /lib /usr.', '/ /lib /lib64 /usr.')\\n            make_pdf(old, old_text)\\n            make_pdf(new, new_text)\\n            calls = []\\n            def generate(prompt):\\n                calls.append(prompt)\\n                return '1' if is_remediation_prompt(prompt) else 'NONE'\\n            options = dict(model_identity='test-double', cache_dir=root/'cache',\\n                           section_limit=1, prompt_types=('zero-shot',))\\n            docs = validate_documents(old, new)\\n            paths = extract_kdes(docs, root/'one', generate, **options)['zero-shot']\\n            self.assertEqual(len(calls), 3)\\n            diff = compare_requirements(load_yaml_pair(*paths), root/'requirements.txt').read_text()\\n            self.assertEqual(diff.strip(), NO_REQUIREMENTS)\\n            self.assertNotIn('/lib64', ' '.join(load_kdes(paths[1])['element1']['requirements']))\\n            context = json.loads((root/'one/source-context.json').read_text())['blocks']\\n            missed = next(b for b in context if b['side'] == 'right'\\n                          and b['source_field'] == 'Description')\\n            self.assertIn('/lib64', ' '.join(missed['source_excerpts']))\\n            self.assertEqual(missed['model_selected_requirements'], [])\\n            self.assertIn('no-model-selection', missed['review_flags'])\\n            review = json.loads((root/'one/extraction-review.json').read_text())\\n            self.assertEqual(review['status'], 'completed-with-review-items')\\n            def no_generation(prompt):\\n                self.fail('The completed responses must be reused without inference.')\\n            refreshed = extract_kdes(docs, root/'two', no_generation, **options)['zero-shot']\\n            self.assertEqual(load_kdes(paths[0]), load_kdes(refreshed[0]))\\n            self.assertEqual(load_kdes(paths[1]), load_kdes(refreshed[1]))\\n            self.assertEqual(json.loads((root/'two/source-context.json').read_text())['blocks'], context)\\n            log = (root/'two/llm-output.txt').read_text()\\n            self.assertIn('*LLM Output*\\\\nNONE', log)\\n            self.assertIn('*Model Selected Requirements*\\\\n[]', log)\\n            self.assertIn('*Coverage Policy*\\\\nmodel-selected-only', log)\\n\\n    def test_missing_model_requirement_still_cannot_complete_recommendation(self):\\n        with tempfile.TemporaryDirectory() as tmp:\\n            root = Path(tmp)\\n            pdf = root/'cis.pdf'\\n            make_pdf(pdf, TEXT)\\n            with self.assertRaises(ValueError):\\n                extract_kdes(validate_documents(pdf, pdf), root/'out', lambda prompt: 'NONE',\\n                             section_limit=1, prompt_types=('zero-shot',), retries=0)\\n            self.assertFalse(list((root/'out').rglob('*-kdes.yaml')))\\n            review = json.loads((root/'out/extraction-review.json').read_text())\\n            self.assertEqual(review['status'], 'incomplete')\\n\\n    def test_description_without_remediation_does_not_turn_none_into_requirement(self):\\n        with tempfile.TemporaryDirectory() as tmp:\\n            root = Path(tmp)\\n            pdf = root/'cis.pdf'\\n            make_pdf(pdf, TEXT.split('Remediation:', 1)[0])\\n            with self.assertRaisesRegex(ValueError, 'no requirements selected'):\\n                extract_kdes(validate_documents(pdf, pdf), root/'out', lambda prompt: 'NONE',\\n                             section_limit=1, prompt_types=('zero-shot',), retries=0)\\n            self.assertFalse(list((root/'out').rglob('*-kdes.yaml')))\\n\\n    def test_old_cache_coverage_metadata_cannot_restore_automatic_additions(self):\\n        with tempfile.TemporaryDirectory() as tmp:\\n            root = Path(tmp)\\n            pdf = root/'cis.pdf'\\n            make_pdf(pdf, TEXT.replace('Containers should run as a non-root user.',\\n                                      'Background information. Containers should run as a non-root user.'))\\n            docs = validate_documents(pdf, pdf)\\n            options = dict(model_identity='test-double', cache_dir=root/'cache',\\n                           section_limit=1, prompt_types=('zero-shot',))\\n            def generate(prompt):\\n                return '1' if is_remediation_prompt(prompt) else '2'\\n            first = extract_kdes(docs, root/'one', generate, **options)['zero-shot']\\n            for path in (root/'cache').glob('*.json'):\\n                cached = json.loads(path.read_text())\\n                cached.update(coverage_policy='retain-complete-remediation',\\n                              included_source_requirements=['Background information.'],\\n                              context_added_ids=[1])\\n                path.write_text(json.dumps(cached))\\n            def no_generation(prompt):\\n                self.fail('Raw responses must be reused, without new calls or context additions.')\\n            second = extract_kdes(docs, root/'two', no_generation, **options)['zero-shot']\\n            self.assertEqual(load_kdes(first[0]), load_kdes(second[0]))\\n            requirements = load_kdes(second[0])['element1']['requirements']\\n            self.assertNotIn('Background information.', requirements)\\n            self.assertIn('Containers should run as a non-root user.', requirements)\\n\\n    def test_complete_selections_finish_without_source_coverage_review_items(self):\\n        with tempfile.TemporaryDirectory() as tmp:\\n            root = Path(tmp)\\n            pdf = root/'cis.pdf'\\n            make_pdf(pdf, TEXT)\\n            extract_kdes(validate_documents(pdf, pdf), root/'out', lambda prompt: '1',\\n                         section_limit=1, prompt_types=('zero-shot',))\\n            review = json.loads((root/'out/extraction-review.json').read_text())\\n            self.assertEqual(review['status'], 'completed')\\n            self.assertEqual(review['items'], [])\\n            # This is source coverage only, not a claim of model accuracy.\\n\\n\\nif __name__ == '__main__':\\n    unittest.main()\\n\",\"original_blob\":\"183ec1f4afd8973d5f917aff101fc62e07226886\"},\"README.md\":{\"updated\":\"# Proj Sec\\n\\n**Version 0.4.0 review:** requirements now contain only actual Gemma selections. The bundled final results and Mac executable are historical version 0.3.0 artifacts; they have not been regenerated for this policy. See [docs/MODEL_SELECTED_REQUIREMENTS.md](docs/MODEL_SELECTED_REQUIREMENTS.md).\\n\\nPublic repository: https://github.com/mondyjackson/proj_sec\\n\\nThe reviewed final outputs are in [submission/final-results.zip](submission/final-results.zip).\\nRestore all five pairs and all 15 scan CSV paths with:\\n\\n```bash\\npython scripts/restore_final_results.py\\n```\\n\\nSee [submission/README.md](submission/README.md) for the bundle contents and hashes.\\n\\n**M1 Mac setup:** start with [TOMORROW_START_HERE.md](TOMORROW_START_HERE.md).\\n\\nCompare CIS Docker Benchmark requirements with **google/gemma-3-1b-it**, then\\nmap relevant changes to Hadolint checks and export scan results. Supported\\nscanner versions are 2.12.0 and 2.15.1, with version-specific rule catalogs.\\n\\nThe remote model revision is pinned to\\n`dcc83ea841ab6100d6b47a070329e1ba4cf78752` for repeatable cache identities.\\n\\n**Status:** all five real Gemma extraction runs and all 15 comparator/scanner\\noutputs have been reviewed. The final Hadolint 2.15.1 scans account for 397,567\\nDockerfiles, including 2,546 parser failures and two files sharing a reproducible\\nupstream runtime error. They are explicitly flagged, not reported as clean scans.\\nSee docs/FINAL_RESULTS_REVIEW.md. Actual GitHub Actions tests and the Linux\\nbuild succeeded; see [docs/GITHUB_ACTIONS.md](docs/GITHUB_ACTIONS.md). Native\\nMac version and real Gemma worker checks also passed; see [docs/MAC_EXECUTABLE.md](docs/MAC_EXECUTABLE.md). The older 2.12.0 dataset baseline is\\nseparate historical evidence in docs/DATASET_VALIDATION.md.\\n\\n## Team\\n\\nIndividual submission; no teammates.\\n\\n| Name | BannerID | University email |\\n| --- | --- | --- |\\n| Jackson Mondy | 904314490 | jbm0138@auburn.edu |\\n\\n## Environment\\n\\nThe core and scanner were checked on Linux x86_64 with Python 3.12. The\\nuser completed real Gemma extraction on native Apple Silicon Python 3.12.16,\\nusing MPS and bfloat16 in the proj-sec Conda environment. Authenticated model\\naccess is required for new inference. Use Python 3.12 for the supplied core\\ndependency lock.\\n\\nCreate and activate a virtual environment:\\n\\n```bash\\npython3 -m venv .venv\\nsource .venv/bin/activate\\npython -m pip install -r requirements.txt\\n```\\n\\nOn Windows use `py -3.12 -m venv .venv` and activate with\\n`.venv\\\\Scripts\\\\Activate.ps1` in PowerShell. Use `python` for subsequent commands.\\n\\nFor core development without model packages, install requirements-core.txt\\ninstead. For a CPU-only Linux PyTorch installation, follow the platform-specific\\ninstructions at https://pytorch.org/get-started/locally/ rather than downloading\\nunneeded CUDA dependencies. Check that the resulting version matches the pin.\\n\\nInstall the pinned Hadolint release:\\n\\n```bash\\npython scripts/install_hadolint.py --output tools\\npython main.py doctor --hadolint tools/hadolint\\n```\\n\\nWindows uses tools/hadolint.exe. On Apple Silicon, use the native Homebrew\\nHadolint 2.15.1 build instead:\\n\\n```bash\\nbrew install hadolint\\nhadolint --version\\npython main.py doctor --hadolint hadolint\\n```\\n\\nUse --hadolint hadolint in direct scan/run commands on this Mac instead of\\n--hadolint tools/hadolint. The five-pair runner now prefers Hadolint on PATH\\nand falls back to the tools directory only when none is found. See the Mac guide.\\nExisting 2.12.0 scan evidence stays valid for that version; rerun final scans\\nwith the chosen binary. The scanner cache includes the binary's SHA-256.\\n\\n## Gemma access\\n\\nLog into Hugging Face and accept the usage conditions at\\nhttps://huggingface.co/google/gemma-3-1b-it. Authenticate from the active virtual\\nenvironment with `hf auth login`. Do not commit credentials. If you already\\nhave the model locally, supply --model-path with that copy of the required model.\\n\\nBefore a full extraction, run one short real-model check:\\n\\n```bash\\npython main.py smoke-model --output outputs/model-smoke\\n```\\n\\nThis downloads/loads the real model. Errors are recorded in gemma-worker.log.\\nThe application does not substitute synthetic responses when access fails.\\n\\nThe smoke-model command uses one short synthetic input. Before a full PDF run,\\ncheck the actual first CIS recommendation with all three prompt styles:\\n\\n```bash\\npython scripts/check_extraction.py --device mps --dtype bfloat16\\n```\\n\\nThis diagnostic samples one recommendation and writes to outputs/extraction-check.\\nIt is not a complete assignment output. Valid results share the normal cache.\\nNew requests ask Gemma to select numbered source excerpts. The production\\nworker constrains generation to valid ID sequences using a token trie;\\nDescription also permits NONE. Python copies the selected text and serializes\\nYAML, so quoted settings and commands do not need to be reproduced inside\\nmodel-generated JSON. The decoder mode is recorded in the runtime and audit.\\nSee docs/CONSTRAINED_SELECTION.md for the implementation and evidence limits. Description and Remediation are\\nprocessed separately for all three prompt styles.\\n\\nOnly excerpts actually selected by Gemma are exported in `requirements`.\\nComplete Description and Remediation text is recorded separately in\\n`source-context.json`. It is not input to requirement comparison.\\n`extraction-review.json` flags source excerpts not selected by the model;\\nthese may be background or missed obligations and require human review.\\nA NONE Description response stays empty. Partial Remediation selections stay\\npartial. Python does not add missing obligations or conditions to the primary output.\\nSee [docs/MODEL_SELECTED_REQUIREMENTS.md](docs/MODEL_SELECTED_REQUIREMENTS.md).\\n\\nKDE names come from PDF headings. Every original model response remains in the\\naudit, alongside source provenance, selected IDs, included IDs, and coverage\\npolicy. A valid ID list proves source fidelity; it does not prove the model\\nselected every obligation. Full extraction and source review remain required.\\n\\nExisting validated JSON responses can be reused through the legacy cache key.\\nTheir actual original prompts and raw outputs stay in the audit, and the same\\nmodel-selected-only policy applies. Invalid responses are not cached.\\nThe earlier bounded JSON punctuation repairs are for legacy responses only.\\n\\n## Inputs and execution\\n\\nPut the three PDFs and the instructor's Dockerfile ZIP in data/. Keep them\\noutside the public repository. The application accepts an archive regardless\\nof whether the instructor's downloaded name is dockerfiles.zip or dokcerfiles.zip.\\n\\nValidate PDFs and inspect section counts before model work:\\n\\n```bash\\npython main.py prepare data/docker-cis-v0.pdf data/docker-cis-v1.pdf --output outputs/preflight\\n```\\n\\nRun extraction alone before reviewing model output:\\n\\n```bash\\npython main.py extract data/docker-cis-v0.pdf data/docker-cis-v1.pdf --output outputs/v0-v1\\n```\\n\\nRun the whole pipeline:\\n\\n```bash\\npython main.py run data/docker-cis-v0.pdf data/docker-cis-v1.pdf --dockerfiles data/dockerfiles.zip --hadolint tools/hadolint --output outputs/v0-v1\\n```\\n\\nRepeat for v0/v2, v1/v2, v1/v1, and v2/v2 with separate output directories.\\nValidated model responses are cached in .cache/gemma and shared across pair\\nfolders and document versions when model identity, source field, and complete\\nprompt match exactly. Every cache hit is revalidated against the current source.\\nConstrained ID requests have a separate namespace and retain fallback access\\nto both previous valid numeric selections and the source-block JSON cache. Earlier combined-source cache\\nentries are not reused. --model-cache selects another directory. Scanner results\\nuse .cache/hadolint.sqlite3 and are keyed by exact Hadolint binary, rule\\nconfiguration, and raw content hash. Rerunning resumes matching requests. Use a new empty --model-cache directory when changing local model weights\\nat the same --model-path; local weight changes are not automatically\\nfingerprinted. Use explicit --device and --dtype settings for repeatable runs.\\n\\nThe frozen executable runs Gemma through the activated virtualenv or Conda\\nenvironment's Python.\\nUse --model-python to select that interpreter explicitly if needed. Model weights\\nand Hadolint are external dependencies; the executable does not embed them.\\n\\n## Outputs\\n\\nThe output directory contains source-context.json, extraction-review.json,\\ninput-inventory.json, source-section JSONs,\\nPROMPT.md with the exact requests, llm-output.txt with the four required labeled\\nfields, cache/, and one directory for each prompt style. Each style directory\\ncontains a document-named left/right YAML pair, both difference TEXT files,\\nhadolint-rules.txt, results.csv, raw findings, a per-file evidence log, and a scan manifest.\\n\\nAll three styles are run independently. Their outputs are retained and compared\\nseparately rather than merging incompatible model responses. A run-status.json\\nrecord distinguishes incomplete work from a completed command.\\n\\nEach CIS recommendation is one KDE. Code assigns its name from the source\\nheading without the number and Manual/Automated suffix. For each prompt style,\\nGemma selects numbered excerpts from Description and Remediation independently.\\nOnly actual selections from both fields are merged into the KDE requirements.\\nBoth present blocks must validate; an empty Description selection is allowed,\\nbut a Remediation response must identify a requirement before the KDE can be\\nexported. A final KDE must have at least one model-selected requirement.\\n\\nThe source splitter preserves every non-whitespace character. Programmatic\\ncopying preserves the text of selected excerpts, including configuration quotes\\nand commands. Supplemental context is stored separately; it does not make the\\nmodel output more complete. A syntactically valid selection can miss an explicit\\ninstruction or select background text. Review the actual outputs before submission.\\n\\nRequirements are compared as sets, preserving case within commands. Names\\nignore whitespace and letter case. The comparator writes the symmetric\\ndifference: both removed and added requirements appear as NAME,REQU CSV tuples\\nwithout a header. Quoting protects embedded commas. This meets the tuple format;\\nthe reports do not label the change direction.\\n\\n## Tests\\n\\n```bash\\npython -m unittest discover -s tests -v\\n```\\n\\nFor real Hadolint integration tests, put a supported binary on PATH or set\\nHADOLINT_BIN to its absolute path. Those integration tests are skipped when no\\nbinary is installed. Unit tests use explicit controlled doubles, including the\\nextractor test; they do not establish real Gemma output quality.\\n\\nSee docs/REQUIREMENTS.md for one-to-one coverage of the 13 required functions\\nand docs/RULE_MAPPING.md for the mapping limitations and severity handling.\\n\\n## GitHub Actions and local git pull\\n\\nThe supplied workflow runs tests on push, pull_request, and manual dispatch,\\nincluding real Hadolint tests without needing model credentials. After tests pass, a separate job builds a Linux executable and uploads it as\\nan artifact with a checksum. Actual test logs are also retained as an artifact.\\nThe [verified workflow run](https://github.com/mondyjackson/proj_sec/actions/runs/45426078503)\\npassed all 97 tests and successfully built and smoke-tested the Linux executable.\\nThe actual test log is preserved in docs/github-actions-test-results.txt.\\n\\nA local git pull is not a native GitHub Actions trigger. An optional post-merge\\nhook runs tests after pulls that merge or fast-forward new commits:\\n\\n```bash\\npython scripts/enable_pull_tests.py\\n```\\n\\nIt does not run on already-up-to-date pulls or cover every rebase scenario.\\nFor guaranteed tests after a successful pull, including up-to-date pulls, use:\\n\\n```bash\\npython scripts/pull_and_test.py\\n```\\n\\nThe hook expects a Python virtualenv. From Conda, use the pull_and_test.py\\nhelper so tests run with the active Conda interpreter. GitHub itself does not\\nreceive events from a local pull; the workflow and local helper cover their\\nrespective environments explicitly.\\n\\n## Executable\\n\\nTo restore the exact verified Apple Silicon Mac build and original archive:\\n\\n```bash\\npython scripts/restore_macos_binary.py\\n./dist/proj-sec --version\\n```\\n\\nSee [SUBMISSION.md](SUBMISSION.md) for the complete handoff, result restoration,\\nand matching platform artifacts. To build locally instead:\\n\\n\\n```bash\\npython -m pip install -r requirements-build.txt\\npython scripts/build.py\\n./dist/proj-sec --help\\n```\\n\\nPyInstaller must run on the target operating system. A Linux binary does not\\nrun on macOS or Windows. The core executable uses the active virtual\\nenvironment's external model worker, so keep the model requirements installed.\\nThe source includes the worker and the build copies it into the executable.\\n\\n## Submission\\n\\nDeadline: **December 1, 2026, 11:59 PM CST**.\\nThe final submission needs a public GitHub repository, actual successful CI\\nlogs, completed team information, real output artifacts, and a verified\\nPyInstaller executable. No Dockerfile dataset upload is required in the repo.\\n\\nSubmission form: https://forms.office.com/r/fMQeqiUbK3\\n\\n## Large archives and Mac memory\\n\\nThe scanner supports the supplied archive's 397,567 Dockerfiles, ignoring Mac\\nmetadata. Batches and workers are bounded, duplicate SHA-256 content shares a\\nscan, and every original path is retained. Runtime crashes/timeouts trigger\\nsmaller retries to isolate affected files; errors are recorded explicitly.\\nOther execution errors stop the run and leave its status incomplete.\\n\\nUse --workers and --batch-size to tune scanning. Raw results are stored once\\nper content in hadolint-findings.jsonl; scan-files.jsonl maps original names to\\ncontent/status. scan-errors.jsonl lists affected paths. DL1000 appears in ALL\\nresults; selected scans retain parse errors in evidence while limiting CSV\\nrows to the selected rules. CSV COUNT remains per original file.\\n\\nThe model supports --dtype auto, float32, float16, or bfloat16. Precision is part\\nof its cache identity. On the M1, test MPS bfloat16 support before choosing the\\nlower-memory option. Supplied Mac results confirm all five extraction pairs\\ncompleted using the required pretrained Gemma model on MPS/bfloat16. The\\nDescription-context correction was verified separately by replaying those\\nrecorded responses without new inference. Gemma is closed\\nbefore scanning to avoid holding the model and large dataframes simultaneously.\\n\\nUse scripts/run_all_pairs.py --mode prepare to inventory all five pairs,\\n--mode extract to produce/review YAMLs, and --mode run to finish the pipeline.\\nThe default mode is prepare and does not download or run Gemma.\\n\\nThe source handoff can be packaged with `python scripts/package_project.py`.\\nThe optional --include-linux-binary flag includes the locally built executable;\\nit does not make that binary runnable on macOS. GitHub Actions also prepares\\na Linux artifact after successful tests once the repository is published.\\n\",\"original_blob\":null},\"SUBMISSION.md\":{\"updated\":\"# Submission handoff\\n\\n**Version 0.4.0 review:** requirements now contain only actual Gemma selections. The bundled final results and Mac executable are historical version 0.3.0 artifacts; they have not been regenerated for this policy. See [docs/MODEL_SELECTED_REQUIREMENTS.md](docs/MODEL_SELECTED_REQUIREMENTS.md).\\n\\nPublic repository: https://github.com/mondyjackson/proj_sec\\n\\n## Contents\\n\\n- Required extractor, comparator, and executor functions and their tests.\\n- All three prompt styles and actual real Gemma response logs.\\n- All five assigned input pairs, including v1/v1 and v2/v2, in the final result bundle.\\n- Complete contributor details in README.md.\\n- Pinned Python requirements, local pull/test helpers, and GitHub Actions.\\n- Actual successful GitHub test logs and a Linux PyInstaller artifact.\\n- The user's runtime-tested native Mac PyInstaller archive and checksum manifest.\\n\\nThe instructor PDFs, Dockerfile dataset, model credentials, and model weights\\nare not committed. Supply authorized inputs separately when rerunning.\\n\\n## Restore the reviewed outputs\\n\\n```bash\\npython scripts/restore_final_results.py\\n```\\n\\nThis restores the 30 YAMLs, actual prompts/LLM logs, comparator/mapping reports,\\nscan statuses/error inventories, and all 15 identical, hash-verified CSV paths.\\nThe CSV copies use about 1.5 GB. No model or scanner rerun is needed to restore them.\\n\\n## Restore the verified Mac executable\\n\\n```bash\\npython scripts/restore_macos_binary.py\\n./dist/proj-sec --version\\n```\\n\\nThe helper reconstructs dist/proj-sec and dist/proj-sec-macos-arm64.tar.gz\\nwith the original verified bytes and executable permissions. Version output is\\n0.3.0. See docs/MAC_EXECUTABLE.md for the real Gemma smoke-test evidence and\\nfull checksum. Linux users should select the Linux executable artifact from\\nthe successful Actions run linked in docs/GITHUB_ACTIONS.md.\\n\\nTo rerun the complete pipeline, follow README.md for the external model-enabled\\nPython environment, Gemma authentication, input paths, and Hadolint setup.\\n\\n## Known result limitations\\n\\nAll original 397,567 Dockerfile paths are accounted for in every scan. The\\nfinal outputs explicitly retain 2,546 DL1000 parser failures and two files\\naffected by a reproducible upstream Hadolint exception. Their statuses are\\ncompleted-with-tool-errors/completed-with-scan-errors, not error-free scans.\\nSee docs/FINAL_RESULTS_REVIEW.md for provenance, counts, and independent checks.\\nActual model selections and source context added by code remain distinguished.\\n\\n## Final user step\\n\\nReview the repository and submit its URL and requested deliverables through\\nthe instructor's form: https://forms.office.com/r/fMQeqiUbK3\\n\\nThe supplied assignment states December 1, 2026, 11:59 PM CST as the deadline.\\nThe submission form has not been submitted by this project preparation process.\\n\",\"original_blob\":null},\"docs/DESCRIPTION_CONTEXT.md\":{\"updated\":\"# Description coverage after the completed Mac extraction\\n\\n> Historical version 0.3.0 policy and evidence. Version 0.4.0 exports only actual model selections and stores source context separately. See [MODEL_SELECTED_REQUIREMENTS.md](MODEL_SELECTED_REQUIREMENTS.md).\\n\\n\\n## What the supplied results establish\\n\\nThe user supplied Proj_Sec_Extraction_Results.zip after all five assigned pairs\\nfinished in extract mode. Review verified all 30 YAML files, 3,522 exported KDEs,\\nand 7,044 validated source-block audit entries. Counts are across repeated pair\\noutputs, not distinct recommendations or fresh model calls. Each original PDF\\nhas 117, 117, or 118 recommendations respectively. The inventories and recorded\\nsource sections match fresh extraction of the supplied PDF bytes. Every exported\\nrequirement is a source excerpt, and all Remediation candidates are present.\\nRepeated documents have consistent YAMLs; both identical-document pairs have\\nidentical outputs for all three prompt styles. The original model-runtime files\\nrecord google/gemma-3-1b-it, revision dcc83ea841ab6100d6b47a070329e1ba4cf78752,\\nMPS, bfloat16, and source-id-trie-v1 for newly constrained generation. Older\\nvalidated numeric/JSON responses are reused and labeled with their original mode.\\n\\n## Coverage failure found during review\\n\\nValid source IDs did not establish semantic completeness. For example, in CIS\\n5.6 the newer Description adds /lib64 to the sensitive host-directory list.\\nZero-shot and chain-of-thought omitted that Description while the associated\\nRemediation contains only a generic prohibition on sensitive mounts. As a result,\\nthose two styles missed the directory-list change. Some old JSON selections\\nalso shortened Description qualifiers even though the selected substring was\\nverbatim. The original results therefore passed syntax and source-fidelity\\nchecks but were not complete with respect to Description content.\\n\\n## Corrected policy and provenance\\n\\nFor a recommendation with a nonempty Remediation block, retain its complete\\nDescription as explicit source context as well as the complete Remediation.\\nEach source block must still have a valid real model response. Remediation must\\ncontain a nonempty valid model selection before the KDE can be exported. NONE\\nin Description remains an empty model selection in the audit; it is not relabeled\\nas a model-selected requirement. The audit separately records included source\\nIDs/text, context added, and retain-description-context-for-remediation policy.\\nWithout Remediation, Description remains model-selected; NONE cannot create a KDE.\\n\\nThis is a hybrid source-context policy, not evidence that Gemma independently\\nidentified every included requirement. It prioritizes preserving source changes\\nand qualifying context, and includes some background prose. On the supplied\\nPDFs, the complete context causes final requirement lists to agree across the\\nthree styles even when their actual model selections differ. The original\\nprompts and responses stay separately recorded for each style. No requirements\\nare paraphrased or invented. Existing valid model responses and cache keys are\\nreused; this correction does not require a new inference run.\\n\\n## Verification\\n\\nAll 97 unit/integration tests passed with real Hadolint 2.15.1, including tests\\nthat reproduce the missed /lib64 change with NONE Description responses,\\npreserve omitted qualifiers from legacy responses, verify cached resumption,\\nand reject recommendations without a valid model-identified requirement.\\n\\nAn offline replay of the uploaded responses applied the revised context policy\\nto all five pairs and all three styles. It made no new model calls. Every source\\ncandidate from both fields was present in the recomputed YAMLs and every included\\nstring was a source excerpt. The /lib64 change was detected in all three styles,\\nand both identical pairs still produced no differences. Expected symmetric\\ndifference counts (individual NAME,REQU tuples count separately) are:\\n\\n| Pair | Name differences | Requirement differences | Mapping |\\n| --- | ---: | ---: | --- |\\n| v0/v1 | 2 | 27 | NO MAPPING FOUND |\\n| v0/v2 | 3 | 32 | NO MAPPING FOUND |\\n| v1/v2 | 1 | 5 | NO MAPPING FOUND |\\n| v1/v1 | 0 | 0 | NO DIFFERENCES FOUND |\\n| v2/v2 | 0 | 0 | NO DIFFERENCES FOUND |\\n\\nThese counts are the same for all three styles. Difference counts measure exact\\ntext, including PDF text-extraction artifacts; they are not counts of distinct\\nsemantic security changes. No supported Dockerfile-rule mapping applies to\\nthese particular differences, so the assignment requires all-rule Hadolint scans.\\n\\nRegenerate the user's final outputs from the preserved local cache after applying\\nthe source update. Do not submit the verification replay as a new model run.\\nFinal Dockerfile scans, repository/Actions, team metadata, and the target-platform\\nPyInstaller executable still need separate completion and verification.\\n\",\"original_blob\":null},\"docs/NUMBERED_SELECTION.md\":{\"updated\":\"# Numbered selection and source coverage\\n\\n> Historical version 0.3.0 policy and evidence. Version 0.4.0 exports only actual model selections and stores source context separately. See [MODEL_SELECTED_REQUIREMENTS.md](MODEL_SELECTED_REQUIREMENTS.md).\\n\\n\\n## Observed problem and model evidence\\n\\nFree-form JSON extraction failed on punctuation and exact copying, including\\nquoted configuration and command examples in CIS 2.2. The Mac diagnostic then\\nasked the same required google/gemma-3-1b-it model to choose numbered source\\nexcerpts. Six of six replies were valid ID lists across two recommendations\\nand all three prompt styles. See mac-selection-check.json for the user-supplied\\nraw selections. Format validity did not establish coverage: the 2.2 selections\\nwere 1,3 (zero-shot), 1,3,5 (few-shot), and 1,4 (chain-of-thought), omitting\\nsome configuration settings, command examples, bridge limitations, or NET_RAW.\\n\\n## Final extraction policy\\n\\n1. Parse each source heading as the KDE identifier and name.\\n2. Process Description and Remediation separately per prompt style.\\n3. Normalize whitespace and split source into numbered exact excerpts. Every\\n   non-whitespace source character must survive splitting.\\n4. Ask real Gemma to select requirement-bearing excerpt IDs. Reject nonexistent\\n   IDs and arbitrary prose. NONE is permitted only for Description.\\n5. After Gemma identifies at least one Remediation requirement, retain the entire\\n   Remediation source and its associated Description as explicitly added context.\\n   Both fields can contain obligations, commands, conditions, or path lists.\\n   The output partitions that source into exact excerpts. Without a Remediation\\n   block, Description remains model-selected.\\n6. Merge both fields into one KDE per recommendation. Do not combine prompt\\n   styles. An absent model response or invalid selection cannot complete a KDE.\\n\\nThe source-context rules are deterministic coverage safeguards, not a\\nclaim that Gemma selected every included excerpt. They favor recall over brevity\\nand can retain explanations alongside obligations. Audit/cache fields separately\\nrecord raw output, model-selected IDs/requirements, included source IDs, added\\ncontext IDs, and coverage policy. Source text added by code is never presented\\nas raw LLM output. No external requirements are invented.\\n\\n## Caches and compatibility\\n\\nFresh constrained requests use the source-selection-trie-v1 namespace. Valid\\nsource-selection-v1 numeric entries and source-block-v1 JSON responses are revalidated and reused when the model, field,\\nand original JSON prompt match. Their actual old prompts stay in the audit;\\nno numeric request is falsely claimed for a cache hit. The original JSON prompt\\nbuilders are retained unchanged for this lookup. Source coverage expansion is\\napplied to reused responses too. Malformed/unmatched legacy output\\nis still rejected. Existing valid work is not discarded or fabricated.\\n\\n## Evidence limits\\n\\nThe supplied Mac results subsequently confirmed all five real full-document\\nextraction runs completed. Review found Description omissions despite valid\\nID syntax. The complete-source-context correction and its offline replay are\\ndocumented in DESCRIPTION_CONTEXT.md. Local unit/integration tests verify\\ncopying, source context, cache compatibility, and Hadolint behavior. These\\nchecks do not establish completed final Dockerfile scans or submission readiness.\\n\\n\\n## Constrained decoding\\n\\nThe production worker now uses a token trie to restrict generated responses to\\nvalid ascending source-ID sequences, with NONE allowed for Description. Syntax\\nvalidity does not establish semantic completeness. See CONSTRAINED_SELECTION.md\\nfor the exact-version API/protocol regression and subsequent Mac evidence.\\n\",\"original_blob\":null},\"docs/MODEL_SELECTED_REQUIREMENTS.md\":{\"updated\":\"# Model-selected requirements, version 0.4.0\\n\\nThe primary KDE requirements now contain exactly the actual Gemma-selected\\nsource excerpts. Deterministic inclusion of complete Description/Remediation\\nblocks has been removed. Source headings still supply KDE names; Python copies\\nselected text and serializes YAML. This is extractive selection, not free-form\\nmodel generation of all names and requirements.\\n\\n## Why this changed\\n\\nThe earlier implementation preserved all source context after a valid model\\nselection. Its audit distinguished that context from the original model output,\\nbut the exported requirements were not exclusively selected by Gemma.\\nVersion 0.4.0 separates those roles.\\n\\nMac diagnostics found real semantic errors. A revised 66-decision sample\\nmatched 41 reviewed labels: zero-shot 12/22, few-shot 19/22, chain-of-thought\\n10/22. For \\\"You should remove any untrusted users from the docker group\\\",\\nGemma's notes identified the action but its final constrained decision was NONE.\\nA small subsequent unrestricted check returned YES for that action but also YES\\nfor the background fact \\\"Docker considers a private registry either secure or\\ninsecure.\\\" These observations do not establish a reliable answer-format fix.\\nThe diagnostic prompts are not substituted for the existing production prompts.\\n\\n## Output and review\\n\\n- YAML requirements: only actual selected excerpts, separately for each style.\\n- source-context.json: complete source blocks, candidate excerpts, actual\\n  model selections, source hashes and locations, and unselected source IDs.\\n- extraction-review.json: completion status and blocks with unselected excerpts\\n  or no model selection. These are review items, not automatic model corrections.\\n- llm-output.txt and PROMPT.md: actual original requests/responses, including\\n  cache provenance. No new request is attributed to a reused response.\\n\\nNONE in Description stays an empty model selection even when Remediation exists.\\nRemediation still requires a valid nonempty selection. A KDE without any\\nmodel-selected requirement fails instead of being filled from source.\\nPartial legacy JSON selections also stay partial; their omitted context is\\navailable only in the supplemental source file.\\n\\nUnselected excerpts can be irrelevant background or genuine missed obligations.\\nSelecting every excerpt is also not proof of semantic accuracy. The review report\\ndoes not certify full coverage. In particular, if Gemma omits the Description\\ncontaining /lib64, the comparator may miss that change; it is not silently repaired.\\n\\n## Reuse and regeneration\\n\\nThe production prompts, model settings, and raw-response cache namespaces have\\nnot changed. Matching genuine responses can be revalidated and reused.\\nOld cached included-source metadata is ignored; requirements are recomputed\\nfrom each raw response under the model-selected-only policy.\\n\\nKeep historical version 0.3.0 outputs separately. After applying the update,\\ngenerate a separate result set:\\n\\n```bash\\ncaffeinate -i python scripts/run_all_pairs.py --mode extract --device mps --dtype bfloat16 --output outputs/model-selected\\n```\\n\\nA cache miss invokes real Gemma. This replay is not a new inference run where\\nresponses are cached. Inspect all five extraction-review.json reports and the\\nactual selected requirements before deciding whether to regenerate comparisons\\nand scans. Prior scan CSVs must not be assumed valid for changed mappings.\\n\\nThe published archive and native Mac executable remain version 0.3.0 evidence.\\nThey do not contain this policy. Rebuild the native executable and check its\\nversion and real model worker after the revised outputs have been reviewed.\\nNo rubric score or full-document accuracy is established by unit tests.\\n\",\"original_blob\":null},\"tests/test_model_selected_update.py\":{\"updated\":\"import tempfile\\nimport unittest\\nfrom pathlib import Path\\n\\nfrom scripts.apply_model_selected_update import apply_update, git_blob_sha\\n\\n\\nclass ModelSelectedUpdateTests(unittest.TestCase):\\n    def prepare(self, root):\\n        (root/'main.py').touch()\\n        (root/'proj_sec').mkdir()\\n        old = 'VALUE = 1\\\\n'\\n        (root/'proj_sec/a.py').write_text(old)\\n        return {\\n            'proj_sec/a.py': {'updated': 'VALUE = 2\\\\n', 'original_blob': git_blob_sha(old.encode())},\\n            'docs/policy.md': {'updated': 'Model-selected requirements.\\\\n', 'original_blob': None},\\n        }\\n\\n    def test_update_preserves_backups_and_a_second_apply_changes_nothing(self):\\n        with tempfile.TemporaryDirectory() as tmp:\\n            root = Path(tmp)\\n            files = self.prepare(root)\\n            result = apply_update(root, files)\\n            self.assertEqual(result['changed'], 2)\\n            backup = Path(result['backup'])\\n            self.assertEqual((backup/'proj_sec/a.py').read_text(), 'VALUE = 1\\\\n')\\n            self.assertEqual((root/'proj_sec/a.py').read_text(), 'VALUE = 2\\\\n')\\n            self.assertTrue((root/'docs/policy.md').is_file())\\n            second = apply_update(root, files)\\n            self.assertEqual(second['changed'], 0)\\n            self.assertIsNone(second['backup'])\\n\\n    def test_unknown_source_revision_fails_before_any_project_file_changes(self):\\n        with tempfile.TemporaryDirectory() as tmp:\\n            root = Path(tmp)\\n            files = self.prepare(root)\\n            (root/'proj_sec/a.py').write_text('VALUE = 99\\\\n')\\n            with self.assertRaisesRegex(ValueError, 'Unexpected source revision'):\\n                apply_update(root, files)\\n            self.assertEqual((root/'proj_sec/a.py').read_text(), 'VALUE = 99\\\\n')\\n            self.assertFalse((root/'docs').exists())\\n            self.assertFalse((root/'.cache').exists())\\n\\n    def test_payload_paths_cannot_escape_the_project(self):\\n        with tempfile.TemporaryDirectory() as tmp:\\n            root = Path(tmp)\\n            self.prepare(root)\\n            with self.assertRaisesRegex(ValueError, 'Unsafe update path'):\\n                apply_update(root, {'../escape.py': {'updated': 'x = 1\\\\n', 'original_blob': None}})\\n            self.assertFalse((root/'.cache').exists())\\n\\n\\nif __name__ == '__main__':\\n    unittest.main()\\n\",\"original_blob\":null}}")


def git_blob_sha(content):
    return hashlib.sha1(b"blob " + str(len(content)).encode() + b"\0" + content).hexdigest()


def apply_update(root, files):
    root = Path(root).expanduser().resolve()
    if not (root/"main.py").is_file() or not (root/"proj_sec").is_dir():
        raise ValueError("Run from the project folder containing main.py and proj_sec.")
    pending = []
    for relative, entry in files.items():
        rel = Path(relative)
        path = root/rel
        if rel.is_absolute() or ".." in rel.parts or not path.resolve().is_relative_to(root):
            raise ValueError(f"Unsafe update path: {relative}")
        desired = entry["updated"].encode("utf-8")
        if path.suffix == ".py":
            compile(entry["updated"], relative, "exec")
        current = path.read_bytes() if path.exists() else None
        if current == desired:
            continue
        expected = entry.get("original_blob")
        if expected and (current is None or git_blob_sha(current) != expected):
            raise ValueError(f"Unexpected source revision: {relative}; no project files changed.")
        pending.append((relative, path, desired))
    if not pending:
        return {"changed": 0, "backup": None}
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ") + "-" + uuid.uuid4().hex[:8]
    backup = root/".cache/model-selected-update-backups"/stamp
    backup.mkdir(parents=True)
    for relative, path, desired in pending:
        if path.exists():
            saved = backup/relative
            saved.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(path, saved)
    for relative, path, desired in pending:
        mode = path.stat().st_mode & 0o777 if path.exists() else 0o644
        path.parent.mkdir(parents=True, exist_ok=True)
        temporary = path.with_name(path.name + ".model-selected.tmp")
        temporary.write_bytes(desired)
        os.chmod(temporary, mode)
        temporary.replace(path)
    (backup/"update-manifest.json").write_text(json.dumps({
        "policy": "model-selected-only", "version": "0.4.0",
        "updated_files": [relative for relative, _, _ in pending],
    }, indent=2) + "\n")
    return {"changed": len(pending), "backup": str(backup)}


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--project", type=Path, default=Path.cwd())
    args = parser.parse_args(argv)
    files = dict(FILES)
    files["scripts/apply_model_selected_update.py"] = {
        "updated": Path(__file__).read_text(encoding="utf-8"), "original_blob": None,
    }
    result = apply_update(args.project, files)
    print(f"Model-selected update: {result['changed']} file(s) changed.")
    if result["backup"]:
        print("Backups:", result["backup"])
    print("Project version: 0.4.0. Existing results, model responses, caches, and binaries were not regenerated.")
    print("Next: python -m unittest discover -s tests -v")
    print("Then regenerate extraction into outputs/model-selected and inspect extraction-review.json.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
